CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS core;
CREATE SCHEMA IF NOT EXISTS community;
CREATE SCHEMA IF NOT EXISTS commerce;
CREATE SCHEMA IF NOT EXISTS integrations;
CREATE SCHEMA IF NOT EXISTS operations;
CREATE SCHEMA IF NOT EXISTS games_atlas;
CREATE SCHEMA IF NOT EXISTS games_7dtd;
CREATE SCHEMA IF NOT EXISTS games_ark;
CREATE TABLE core.principals(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),principal_type TEXT NOT NULL CHECK(principal_type IN('user','service')),status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','active','suspended','disabled','deletion_pending','deleted')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE core.users(principal_id UUID PRIMARY KEY REFERENCES core.principals(id),username TEXT NOT NULL,email TEXT,email_verified_at TIMESTAMPTZ,password_hash TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CONSTRAINT users_username_format CHECK(username ~ '^[A-Za-z0-9_]{3,32}$'));
CREATE UNIQUE INDEX users_username_lower_uq ON core.users(LOWER(username));
CREATE UNIQUE INDEX users_email_lower_uq ON core.users(LOWER(email)) WHERE email IS NOT NULL;
CREATE TABLE core.user_profiles(principal_id UUID PRIMARY KEY REFERENCES core.users(principal_id) ON DELETE CASCADE,display_name TEXT,avatar_url TEXT,timezone TEXT NOT NULL DEFAULT 'UTC',updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE core.linked_accounts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),principal_id UUID NOT NULL REFERENCES core.users(principal_id),provider TEXT NOT NULL CHECK(provider IN('discord','steam','atlas','7dtd','ark','other')),external_id TEXT NOT NULL,external_username TEXT,verified_at TIMESTAMPTZ NOT NULL,linked_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),unlinked_at TIMESTAMPTZ,UNIQUE(provider,external_id));
CREATE INDEX linked_accounts_principal_idx ON core.linked_accounts(principal_id);
CREATE TABLE core.identity_verifications(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),principal_id UUID NOT NULL REFERENCES core.users(principal_id),provider TEXT NOT NULL,external_id TEXT NOT NULL,method TEXT NOT NULL,challenge_hash TEXT NOT NULL,expires_at TIMESTAMPTZ NOT NULL,verified_at TIMESTAMPTZ,attempts SMALLINT NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 10),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE core.auth_sessions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),principal_id UUID NOT NULL REFERENCES core.principals(id),token_hash TEXT NOT NULL UNIQUE,expires_at TIMESTAMPTZ NOT NULL,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_used_at TIMESTAMPTZ);
CREATE INDEX auth_sessions_principal_idx ON core.auth_sessions(principal_id);
CREATE TABLE core.roles(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),name TEXT NOT NULL UNIQUE,description TEXT);
CREATE TABLE core.permissions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),permission_key TEXT NOT NULL UNIQUE,description TEXT);
CREATE TABLE core.role_permissions(role_id UUID NOT NULL REFERENCES core.roles(id) ON DELETE CASCADE,permission_id UUID NOT NULL REFERENCES core.permissions(id) ON DELETE CASCADE,PRIMARY KEY(role_id,permission_id));
CREATE TABLE core.principal_role_assignments(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),principal_id UUID NOT NULL REFERENCES core.principals(id),role_id UUID NOT NULL REFERENCES core.roles(id),scope_type TEXT NOT NULL CHECK(scope_type IN('platform','game','cluster','server','guild')),scope_id TEXT,granted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),expires_at TIMESTAMPTZ,granted_by UUID REFERENCES core.principals(id),CHECK((scope_type='platform' AND scope_id IS NULL) OR(scope_type<>'platform' AND scope_id IS NOT NULL)));
CREATE INDEX role_assignments_lookup_idx ON core.principal_role_assignments(principal_id,scope_type,scope_id);
CREATE TABLE core.service_accounts(principal_id UUID PRIMARY KEY REFERENCES core.principals(id),application_name TEXT NOT NULL,credential_hash TEXT NOT NULL,credential_rotated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE core.games(id TEXT PRIMARY KEY,name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN('planned','active','paused','retired')));
INSERT INTO core.games(id,name,status) VALUES('atlas','ATLAS','active'),('7dtd','7 Days to Die','active'),('ark','ARK: Survival Evolved','planned') ON CONFLICT(id) DO NOTHING;
CREATE TABLE core.clusters(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),game_id TEXT NOT NULL REFERENCES core.games(id),name TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN('planned','online','offline','maintenance')),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE core.servers(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),cluster_id UUID NOT NULL REFERENCES core.clusters(id),external_server_id TEXT,name TEXT NOT NULL,host_label TEXT,status TEXT NOT NULL DEFAULT 'unknown' CHECK(status IN('unknown','online','offline','maintenance')),last_heartbeat_at TIMESTAMPTZ,UNIQUE(cluster_id,external_server_id));
CREATE TABLE operations.audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),actor_principal_id UUID REFERENCES core.principals(id),action TEXT NOT NULL,resource_type TEXT,resource_id TEXT,outcome TEXT NOT NULL CHECK(outcome IN('success','failure','denied')),metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX audit_logs_actor_time_idx ON operations.audit_logs(actor_principal_id,created_at DESC);
CREATE TABLE operations.event_outbox(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),event_type TEXT NOT NULL,aggregate_type TEXT NOT NULL,aggregate_id TEXT NOT NULL,payload JSONB NOT NULL,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),available_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),published_at TIMESTAMPTZ,attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT);
CREATE INDEX event_outbox_pending_idx ON operations.event_outbox(available_at,occurred_at) WHERE published_at IS NULL;
CREATE TABLE operations.event_deliveries(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),event_id UUID NOT NULL REFERENCES operations.event_outbox(id) ON DELETE CASCADE,consumer TEXT NOT NULL,delivered_at TIMESTAMPTZ,attempts INTEGER NOT NULL DEFAULT 0,last_error TEXT,UNIQUE(event_id,consumer));
